Given an integer array arr[] of size n, find the maximum value of the expression i * arr[i] (for all i from 0 to n-1) after rotating the array any number of times.Examples:  Input: arr[] = [8, 3, 1, 2]Output: 29Explanation: Out of all the possible configurations by rotating the elements: arr[] = [3, 1, 2, 8] here (3*0) + (1*1) + (2*2) + (8*3) sum is maximum i.e. 29.Input: arr[] = [1, 2, 3]Output: 8Explanation: Out of all the possible configurations by rotating the elements: arr[] = [1, 2, 3] here (1*0) + (2*1) + (3*2) sum is maximum i.e. 8.Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n ^ 2) Time and O(1) Space[Expected Approach] Using Mathematics - O(n) Time and O(1) Space[Alternate Approach] Using Pivot - O(n) Time and O(1) Space[Naive Approach] Using Nested Loops - O(n ^ 2) Time and O(1) SpaceThe idea is to find the sum of all the elements of the array for each possible rotation, and store the maximum of them as answer. To do so, use nested loops, where the outer loop marks the starting point of the array, and the inner loop iterates through each of the element, and store the sum of i * arr[i]. Check if the maximum sum is greater than the current sum then update the maximum sum.
            C++

    #include <iostream>
#include <vector>
#include <limits.h>
using namespace std;

int maxSum(vector<int> &arr) {
    int n = arr.size();

    int res = INT_MIN;

    // Consider rotation beginning with i
    // for all possible values of i.
    for (int i = 0; i < n; i++) {

        // Initialize sum of current rotation
        int sum = 0;

        // Compute sum of all values
        for (int j = 0; j < n; j++) {

            // compute the rotated index
            int index = (i + j) % n;
            sum += j * arr[index];
        }

        // Update the maximum value
        res = max(res, sum);
    }

    return res;
}

int main() {
    vector<int> arr = {8, 3, 1, 2};
    cout << maxSum(arr);
    return 0;
}


