Output29[Alternate Approach] Using Pivot - O(n) Time and O(1) SpaceNote: This approach works only for sorted or rotated sorted arrays.We know for an array the maximum sum will be when the array is sorted in ascending order. In case of a sorted rotated array, we can rotate the array to make it in ascending order. So, in this case, the pivot element is needed to be found following which the maximum sum can be calculated.Find the pivot of the array: if arr[i] > arr[(i+1)%n] then it is the pivot element. (i+1)%n is used to check for the last and first element.After getting pivot the sum can be calculated by finding the difference with the pivot which will be the multiplier and multiply it with the current element while calculating the sum
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Function to find pivot 
int findPivot(vector<int> &arr)  { 
    int n = arr.size();

    for(int i = 0; i < n; i++) { 
        if(arr[i] > arr[(i + 1) % n]) 
            return i; 
    } 

    return 0;
} 

// Function to find maximum sum rotation
int maxSum(vector<int> &arr) {
    int n = arr.size();

    // initialize result
    int res = 0; 
    int pivot = findPivot(arr); 

    // difference in pivot and index of 
    // last element of array 
    int diff = n - 1 - pivot; 

    // compute the sum
    for(int i = 0; i < n; i++) { 
        res = res + ((i + diff) % n) * arr[i]; 
    } 
    return res; 
} 

int main() {
    vector<int> arr = {8, 3, 1, 2};
    cout << maxSum(arr);
    return 0;
}


